/**
 * Curated Explore destinations.
 *
 * Easy to edit: add, remove or tweak entries below. Keep descriptions short and original.
 * Coordinates are TripTwin's own picks (a central square or landmark), not Google data.
 *
 * Google Place IDs and Street View checks live in `destinations.verified.json`, which is
 * generated by `npm run verify:destinations` (see README). Only destinations that pass the
 * Street View check are featured in production.
 *
 * tier: 1 = always visible on the globe, 2 = appears when zoomed in a bit, 3 = only when close.
 */
export type DestinationType = 'city' | 'town';
export type Continent = 'Africa' | 'Asia' | 'Europe' | 'North America' | 'South America' | 'Oceania';

export interface Destination {
  id: string;
  name: string;
  country: string;
  continent: Continent;
  type: DestinationType;
  lat: number;
  lng: number;
  tier: 1 | 2 | 3;
  description: string;
}

type Row = [id: string, name: string, country: string, continent: Continent, type: DestinationType, lat: number, lng: number, tier: 1 | 2 | 3, description: string];

